        key,h,w=m[1],int(m.group(2)),int(m.group(3))
        pos=m.end(); rows=[]
        for line in t[pos:].split('\n'):
            parts=line.split()
            if len(parts)==w and all(x.isdigit() for x in parts):
                rows.append([int(x) for x in parts])
                if len(rows)==h: break
        if len(rows)!=h: continue
        G[key]=rows
    return G
